import {translations} from './i18n.mjs';
const entries={"settlement":["Savings settlement","Gusubiza ubwizigame","Règlement de l’épargne"],"remainingSavings":["Remaining savings","Ubwizigame busigaye","Épargne restante"],"withdrawal":["Savings withdrawal","Gusubiza ubwizigame","Retrait d’épargne"],"withdrawalRequest":["Request withdrawal","Saba gusubizwa ubwizigame","Demander un retrait"],"withdrawalReview":["Review withdrawal","Suzuma gusubizwa ubwizigame","Examiner le retrait"],"withdrawalPay":["Confirm withdrawal paid","Emeza ubwizigame bwasubijwe","Confirmer le retrait payé"],"settlementHelp":["Approval does not move money. The treasurer confirms external payment. Open loans block payment. Amounts cannot exceed member savings or available funds. Paid withdrawals are permanent in this version.","Kwemeza ntibimura amafaranga. Umubitsi yemeza ubwishyu bwakorewe hanze. Inguzanyo zitararangira zibuza gusubizwa ubwizigame. Amafaranga ntarenza ubwizigame cyangwa amafaranga ahari. Ubwishyu bwemejwe ntibusubirwaho muri iyi verisiyo.","L’approbation ne déplace pas de fonds. Le trésorier confirme le paiement externe. Les prêts ouverts bloquent le paiement. Le montant ne dépasse ni l’épargne ni les fonds disponibles. Les retraits payés sont définitifs dans cette version."]};
for(const [key,values] of Object.entries(entries))for(const [i,lang] of ['en','rw','fr'].entries())translations[lang][key]=values[i];

const auditLabels={withdrawalRequested:['Withdrawal requested','Gusubizwa ubwizigame byasabwe','Retrait demandé'],withdrawalReviewed:['Withdrawal reviewed','Gusubizwa ubwizigame byasuzumwe','Retrait examiné'],withdrawalPaid:['Withdrawal paid','Ubwizigame bwasubijwe','Retrait payé'],withdrawalCancelled:['Withdrawal cancelled','Gusubizwa ubwizigame byahagaritswe','Retrait annulé']};
for(const [key,values] of Object.entries(auditLabels))for(const [i,lang] of ['en','rw','fr'].entries())translations[lang][key]=values[i];
